action_input.code:
def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True
prime_sum = sum([n for n in range(2, 100) if is_prime(n)])
print(prime_sum)

